```function set-zeno-pid() {
  if [[ ! -z $ZENO_ENABLE_SOCK ]] &amp;&amp; [[ -z $ZENO_PID ]]; then
    local out=$(zeno-client "--mode=pid")
    export ZENO_PID=$out
  fi
}```
