```  export ZENO_BIN_PATH=${0:a:h}/bin/zeno

  function clear-zeno-client() {
    if [[ -S ${ZENO_SOCK} ]]; then
      rm ${ZENO_SOCK}
    fi

    nohup "${ZENO_BIN_PATH}" &gt;/dev/null 2&gt;&amp;1 &amp;!
    export ZENO_PID=$!
  }

  add-zsh-hook precmd clear-zeno-client

  nohup "${ZENO_BIN_PATH}" &gt;/dev/null 2&gt;&amp;1 &amp;!```
